package com.campusnova.config;
import com.campusnova.model.OfficialKnowledge; import com.campusnova.repository.OfficialKnowledgeRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*;
/** Minimal profile record; admins import current, detailed official pages using the protected importer. */
@Configuration public class LbscekSeedConfig { @Bean CommandLineRunner lbscekProfile(OfficialKnowledgeRepository docs,CollegeProfile profile){return args->{if(docs.count()==0){OfficialKnowledge identity=new OfficialKnowledge(profile.getOfficialDomain(),"L B S College of Engineering — official profile","COLLEGE_PROFILE","College Information",profile.getOfficialName()+" is located at "+profile.getAddress()+". It is a "+profile.getInstitutionType()+" and is affiliated to "+profile.getAffiliation()+". Official website: "+profile.getOfficialDomain());identity.setOfficialSource(true);identity.setVerified(true);docs.save(identity);}};} }
